import React, { useState } from "react";
import {
  ListItem,
  ListItemText,
  IconButton,
  Checkbox,
  ListItemIcon,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";

function TodoItem({ todo, toggleTodo, deleteTodo }) {
  const [open, setOpen] = useState(false);

  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  const handleDelete = () => {
    deleteTodo(todo.id);
    handleClose();
  };
  return (
    <>
      secondaryAction=
      {
        <IconButton edge="end" color="error" onClick={handleOpen}>
          <DeleteIcon />
        </IconButton>
      }
      <Dialog open={open} onclick={handleClose}>
        <DialogTitle>Confirmar deleção?</DialogTitle>
        <DialogContent>Você realmente quer deletar esta tarefa?</DialogContent>
        <DialogActions>
          <Button onclick={handleClose} color="primary">
            Cancelar
          </Button>
          <Button onclick={handleDelete} color="error" variant="contained">
            Deletar
          </Button>
        </DialogActions>
      </Dialog>
      <ListItem
        secondaryAction={
          <IconButton edge="end" color="error" onClick={handleOpen}>
            <DeleteIcon />
          </IconButton>
        }
      >
        <ListItemIcon>
          <Checkbox
            edge="start"
            checked={todo.completed}
            onChange={() => toggleTodo(todo.id)}
          />
        </ListItemIcon>

        <ListItemText
          primary={todo.text}
          secondary={`Adicionado às ${todo.createdAt}`}
          sx={{
            textDecoration: todo.completed ? "line-through" : "none",
            color: todo.completed ? "gray" : "inherit",
            wordBreak: "break-word",
            whiteSpace: "pre-wrap",
            overflow: "break-word",
          }}
        />
      </ListItem>
      <Dialog open={open} onClose={handleClose}>
        <DialogTitle>condfirmar deleção</DialogTitle>
        <DialogContent>Você realmente quer deletar esta tarefa?</DialogContent>
        <dialogActions>
          <Button onClick={handleClose} color="primary">
            Cancelar
          </Button>
          <Button onclick={handleDelete} color="error" variant="contained">
            Deleter
          </Button>
        </dialogActions>
      </Dialog>
    </>
  );
}

export default TodoItem;
